  'about.statTotal': 'Wpisy na mapie',
  'about.statBase': 'Wpisy bazowe',
  'about.statAdded': 'Nowo dodane zdarzenia',
  'about.statCandidates': 'Niezidentyfikowane obiekty (Ostrzeżenie / inne)',
